#!/usr/bin/env node

/**
 * Custom Path-Based Coverage Checker for Okaeri Resort System
 *
 * This script implements path-based coverage thresholds that Vitest doesn't support natively.
 * It reads the coverage-summary.json file generated by Vitest and checks coverage for specific paths.
 *
 * Usage:
 *   node scripts/check-coverage.js
 *   npm run verify:coverage:paths
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { dirname } from "path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Phase-specific coverage requirements
const COVERAGE_THRESHOLDS = {
  // Phase 1 - Authentication (95% coverage required)
  "src/features/auth": {
    branches: 95,
    functions: 95,
    lines: 95,
    statements: 95,
  },
  // Phase 2 - Dashboard (90% coverage - baseline)
  "src/features/dashboard": {
    branches: 90,
    functions: 90,
    lines: 90,
    statements: 90,
  },
  // Phase 3 - Booking (95% coverage required - critical business logic)
  "src/features/booking": {
    branches: 95,
    functions: 95,
    lines: 95,
    statements: 95,
  },
  // Phase 4 - Financial (95% coverage required)
  "src/features/financial": {
    branches: 95,
    functions: 95,
    lines: 95,
    statements: 95,
  },
  // Phase 5 - Deployment (90% coverage - baseline)
  "src/features/deployment": {
    branches: 90,
    functions: 90,
    lines: 90,
    statements: 90,
  },
  // Core utilities (95% coverage required)
  "src/lib": {
    branches: 95,
    functions: 95,
    lines: 95,
    statements: 95,
  },
  // Store management (93% coverage required)
  "src/stores": {
    branches: 93,
    functions: 93,
    lines: 93,
    statements: 93,
  },
};

const COVERAGE_FILE = path.join(process.cwd(), "coverage", "coverage-summary.json");

/**
 * Reads and parses the coverage summary file
 */
function readCoverageSummary() {
  try {
    if (!fs.existsSync(COVERAGE_FILE)) {
      console.error(`❌ Coverage file not found: ${COVERAGE_FILE}`);
      console.error('💡 Run "npm run test:coverage" first to generate coverage data');
      process.exit(1);
    }

    const coverageData = JSON.parse(fs.readFileSync(COVERAGE_FILE, "utf8"));
    return coverageData;
  } catch (error) {
    console.error(`❌ Error reading coverage file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Calculates coverage metrics for a specific path pattern
 */
function calculatePathCoverage(coverageData, pathPattern) {
  const metrics = {
    branches: { covered: 0, total: 0 },
    functions: { covered: 0, total: 0 },
    lines: { covered: 0, total: 0 },
    statements: { covered: 0, total: 0 },
  };

  const files = Object.keys(coverageData).filter((filePath) => {
    // Normalize path separators for cross-platform compatibility
    const normalizedPath = filePath.replace(/\\/g, "/");
    const normalizedPattern = pathPattern.replace(/\\/g, "/");
    return normalizedPath.startsWith(normalizedPattern);
  });

  if (files.length === 0) {
    return null; // No files found for this path pattern
  }

  // Aggregate coverage across all files in the path
  files.forEach((filePath) => {
    const fileData = coverageData[filePath];

    if (fileData.branches) {
      metrics.branches.covered += fileData.branches.covered;
      metrics.branches.total += fileData.branches.total;
    }
    if (fileData.functions) {
      metrics.functions.covered += fileData.functions.covered;
      metrics.functions.total += fileData.functions.total;
    }
    if (fileData.lines) {
      metrics.lines.covered += fileData.lines.covered;
      metrics.lines.total += fileData.lines.total;
    }
    if (fileData.statements) {
      metrics.statements.covered += fileData.statements.covered;
      metrics.statements.total += fileData.statements.total;
    }
  });

  // Calculate percentages
  const result = {
    files: files.length,
    branches:
      metrics.branches.total > 0 ? (metrics.branches.covered / metrics.branches.total) * 100 : 100,
    functions:
      metrics.functions.total > 0
        ? (metrics.functions.covered / metrics.functions.total) * 100
        : 100,
    lines: metrics.lines.total > 0 ? (metrics.lines.covered / metrics.lines.total) * 100 : 100,
    statements:
      metrics.statements.total > 0
        ? (metrics.statements.covered / metrics.statements.total) * 100
        : 100,
  };

  return result;
}

/**
 * Checks if coverage meets the threshold requirements
 */
function checkThreshold(actual, required, metricName) {
  const passes = actual >= required;
  const status = passes ? "✅" : "❌";
  const formattedActual = actual.toFixed(1);

  return {
    passes,
    message: `${status} ${metricName}: ${formattedActual}% (required: ${required}%)`,
  };
}

/**
 * Main coverage checking function
 */
function checkCoverage() {
  console.log("🔍 Running Path-Based Coverage Analysis...\n");

  const coverageData = readCoverageSummary();
  let allPassed = true;
  let checkedPaths = 0;

  // Check each path pattern
  for (const [pathPattern, thresholds] of Object.entries(COVERAGE_THRESHOLDS)) {
    const coverage = calculatePathCoverage(coverageData, pathPattern);

    if (!coverage) {
      console.log(`⚠️  No files found for path: ${pathPattern}`);
      continue;
    }

    checkedPaths++;
    console.log(`\n📁 Path: ${pathPattern} (${coverage.files} files)`);

    // Check each metric
    const branchCheck = checkThreshold(coverage.branches, thresholds.branches, "Branches");
    const functionCheck = checkThreshold(coverage.functions, thresholds.functions, "Functions");
    const lineCheck = checkThreshold(coverage.lines, thresholds.lines, "Lines");
    const statementCheck = checkThreshold(coverage.statements, thresholds.statements, "Statements");

    console.log(`  ${branchCheck.message}`);
    console.log(`  ${functionCheck.message}`);
    console.log(`  ${lineCheck.message}`);
    console.log(`  ${statementCheck.message}`);

    if (
      !branchCheck.passes ||
      !functionCheck.passes ||
      !lineCheck.passes ||
      !statementCheck.passes
    ) {
      allPassed = false;
    }
  }

  // Summary
  console.log(`\n${"=".repeat(60)}`);
  if (allPassed) {
    console.log("✅ All path-based coverage thresholds passed!");
    console.log(`📊 Checked ${checkedPaths} path patterns successfully`);
    process.exit(0);
  } else {
    console.log("❌ Some path-based coverage thresholds failed!");
    console.log(`📊 Checked ${checkedPaths} path patterns with failures`);
    console.log("\n💡 Tips to improve coverage:");
    console.log("  • Add unit tests for uncovered functions");
    console.log("  • Test error handling and edge cases");
    console.log("  • Verify all code branches are tested");
    console.log('  • Use "npm run test:coverage" to see detailed reports');
    process.exit(1);
  }
}

// Show global coverage summary
function showGlobalSummary(coverageData) {
  const total = coverageData.total;
  if (total) {
    console.log("📊 Global Coverage Summary:");
    console.log(`  Branches: ${total.branches.pct}%`);
    console.log(`  Functions: ${total.functions.pct}%`);
    console.log(`  Lines: ${total.lines.pct}%`);
    console.log(`  Statements: ${total.statements.pct}%`);
  }
}

// Run the coverage check
if (import.meta.url === `file://${process.argv[1]}`) {
  try {
    const coverageData = readCoverageSummary();
    showGlobalSummary(coverageData);
    checkCoverage();
  } catch (error) {
    console.error(`❌ Coverage check failed: ${error.message}`);
    process.exit(1);
  }
}

export { checkCoverage, calculatePathCoverage, COVERAGE_THRESHOLDS };
